<?php
namespace App\Http\Controllers;
use App\Models\Product; use Illuminate\Http\Request;
class ProductController extends Controller { public function index(){return view('products.index',['products'=>Product::paginate(5)]);} public function create(){return view('products.form',['product'=>new Product]);} public function store(Request $r){Product::create($this->valid($r));return redirect()->route('produtos.index')->with('success','Produto cadastrado com sucesso.');} public function edit(Product $produto){return view('products.form',['product'=>$produto]);} public function update(Request $r,Product $produto){$produto->update($this->valid($r));return redirect()->route('produtos.index')->with('success','Produto atualizado.');} public function destroy(Product $produto){$produto->delete();return back()->with('success','Produto excluído.');} private function valid(Request $r){return $r->validate(['name'=>'required|string|max:120','category'=>'required','price'=>'required|numeric|min:0','stock'=>'required|integer|min:0','minimum_stock'=>'required|integer|min:0']);}}
